def test_escape() -> None:
    def decode(value: Text) -> Text:
        match = re.fullmatch(r"\\(.*)", value, flags=re.DOTALL)
        assert match is not None
        return escape(match)

    for tail, expected in simple_escapes.items():
        assert decode("\\" + tail) == expected

    assert decode(r"\x00") == "\x00"
    assert decode(r"\x41") == "A"
    assert decode(r"\xff") == "\xff"

    assert decode(r"\0") == "\0"
    assert decode(r"\7") == "\7"
    assert decode(r"\101") == "A"
    assert decode(r"\377") == "\xff"

    for value, expected_message in (
        (r"\x", r"invalid hex string escape ('\x')"),
        (r"\x1", r"invalid hex string escape ('\x1')"),
        (r"\xzz", r"invalid hex string escape ('\xzz')"),
        (r"\8", r"invalid octal string escape ('\8')"),
    ):
        try:
            decode(value)
        except ValueError as error:
            assert str(error) == expected_message
        else:
            raise AssertionError("ValueError not raised for %r" % value)

